//! Numerical integration in one variable: fixed Gauss–Legendre rules, and an adaptive integrator
//! on Gauss–Kronrod rules with an error estimate.
//!
//! What it does: [`gauss_legendre`] applies an n-point Gauss–Legendre rule (n from 1 to 20) on
//! `[a, b]`. [`integrate`] estimates ∫ₐᵇ f by one of the six Gauss–Kronrod rules
//! ([`crate::quadrature_rules::GAUSS_KRONROD`]), splitting the panel with the largest error estimate
//! in two until the summed estimate meets the tolerance: QUADPACK's QAG strategy. The rules are
//! generated by geom-gen, every node and weight correctly rounded (`quadrature_rules`'s header).
//! Chapter 12's transcendental enclosures (the Fresnel integrals of clothoids) integrate with the
//! Gauss–Legendre rules and bound the remainder themselves; [`integrate`]'s estimate is for
//! measures that need no proof (an arc length to report, a mass property).
//!
//! Guarantees:
//!
//! - **Exact to the rules' degrees.** The n-point Gauss rule integrates every polynomial of degree
//!   at most 2n − 1, and a Kronrod rule of 2n + 1 points every one of degree at most 3n + 1, up to
//!   the rounding of the rule's entries and of the sum (`tests/quadrature.rs` checks every rule
//!   against exact rational integrals).
//! - **An estimate, labelled as one.** [`Integral::error`] is the sum over panels of
//!   |Kronrod − Gauss|, Kronrod's classic estimate of the Gauss result's error, which for smooth
//!   functions far exceeds the Kronrod result's. It is not a bound: a caller that needs a proven
//!   bound encloses the remainder from a derivative bound instead (chapter 12.10).
//! - **A cap, never a guess.** At most `cap` bisections, and at most [`MAX_PANELS`] panels;
//!   reaching either without meeting the tolerance is [`QuadError::CapReached`], never the best
//!   value so far.
//! - **Deterministic and order-free.** Panels are evaluated and split in a fixed order (the first
//!   panel with the largest estimate is split, left half in its place, right half last), every sum
//!   is taken exactly with [`ExactSum`] and rounded once, and the result is a finite [`Real`]; the
//!   same bits on every target.
//!
//! Method: the Gauss–Kronrod pair and the adaptive bisection of R. Piessens, E. de Doncker-Kapenga,
//! C. W. Überhuber and D. K. Kahaner, *QUADPACK: A Subroutine Package for Automatic Integration*,
//! Springer (1983), doi:10.1007/978-3-642-61786-7, routines QK and QAG; the error estimate
//! |K − G| is Kronrod's (A. S. Kronrod, *Nodes and Weights of Quadrature Formulas*, Consultants
//! Bureau (1965)), without QUADPACK's empirical rescaling.
//!
//! Cost: [`gauss_legendre`] is n evaluations of f and an exact sum; [`integrate`] is 2n + 1
//! evaluations per panel, at most `cap` + 1 panels, and a search of at most [`MAX_PANELS`] panels
//! per bisection. No allocation (the panels live in a fixed array on the stack, 40 bytes each), no
//! recursion.

use crate::error::NumError;
use crate::exact_sum::ExactSum;
use crate::quadrature_rules::{GAUSS_KRONROD, GAUSS_LEGENDRE};
use crate::real::Real;

/// The most panels [`integrate`] keeps: the work list's fixed size.
pub const MAX_PANELS: usize = 128;

/// A Gauss–Legendre rule on [−1, 1]: nodes ascending, and their weights.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct GaussRule {
    /// The nodes, ascending.
    pub nodes: &'static [f64],
    /// The weight of each node.
    pub weights: &'static [f64],
}

/// A Gauss–Kronrod rule on [−1, 1]: 2n + 1 nodes ascending, the Gauss nodes at the odd positions.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct KronrodRule {
    /// The 2n + 1 nodes, ascending.
    pub nodes: &'static [f64],
    /// The Kronrod weight of each node.
    pub kronrod: &'static [f64],
    /// The Gauss weight of each Gauss node, the odd positions of `nodes`, in order.
    pub gauss: &'static [f64],
}

/// Why an integral could not be given.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum QuadError {
    /// `a` is not below `b`, or a tolerance is negative.
    BadInterval,
    /// No rule of that size: Gauss–Legendre has 1 to 20 points, and there are six Kronrod rules.
    NoSuchRule,
    /// The tolerance was not met within `cap` bisections or [`MAX_PANELS`] panels.
    CapReached,
    /// A panel became too narrow to split in `f64`.
    TooNarrow,
    /// The function, or a sum, failed.
    Num(NumError),
}

impl From<NumError> for QuadError {
    fn from(e: NumError) -> Self {
        QuadError::Num(e)
    }
}

impl core::fmt::Display for QuadError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            QuadError::BadInterval => {
                f.write_str("the interval is empty or reversed, or a tolerance is negative")
            }
            QuadError::NoSuchRule => f.write_str("no quadrature rule of that size"),
            QuadError::CapReached => f.write_str("the tolerance was not met within the cap"),
            QuadError::TooNarrow => f.write_str("a panel became too narrow to split"),
            QuadError::Num(e) => e.fmt(f),
        }
    }
}

/// An integral from [`integrate`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Integral {
    /// The Kronrod estimate of ∫ₐᵇ f.
    pub value: Real,
    /// The error estimate: Σ |Kronrod − Gauss| over the panels (not a bound).
    pub error: Real,
    /// How many panels the interval ended in.
    pub panels: u32,
    /// How many times f was evaluated.
    pub evaluations: u32,
}

/// The point `centre + half · t` and its value.
fn value_at<F>(f: &mut F, centre: f64, half: f64, t: f64) -> Result<f64, QuadError>
where
    F: FnMut(Real) -> Result<Real, NumError>,
{
    Ok(f(Real::new(centre + half * t)?)?.get())
}

/// The n-point Gauss–Legendre estimate of ∫ₐᵇ f, n from 1 to 20.
///
/// # Errors
///
/// [`QuadError::BadInterval`] if `a ≥ b`; [`QuadError::NoSuchRule`] for any other n;
/// [`QuadError::Num`] if f fails or the sum overflows.
pub fn gauss_legendre<F>(mut f: F, a: Real, b: Real, n: usize) -> Result<Real, QuadError>
where
    F: FnMut(Real) -> Result<Real, NumError>,
{
    let (a, b) = (a.get(), b.get());
    if a >= b {
        return Err(QuadError::BadInterval);
    }
    let rule = n
        .checked_sub(1)
        .and_then(|i| GAUSS_LEGENDRE.get(i))
        .ok_or(QuadError::NoSuchRule)?;
    let (centre, half) = (0.5 * a + 0.5 * b, 0.5 * b - 0.5 * a);
    let mut sum = ExactSum::new();
    for (t, w) in rule.nodes.iter().zip(rule.weights) {
        sum.add(w * value_at(&mut f, centre, half, *t)?);
    }
    Ok(Real::new(half * sum.round()?.get())?)
}

/// One panel: its ends, its Kronrod value and its error estimate.
#[derive(Clone, Copy, Debug)]
struct Panel {
    a: f64,
    b: f64,
    value: f64,
    error: f64,
}

/// The most nodes a Kronrod rule has: G30K61's 61.
const MAX_NODES: usize = 61;

/// The Kronrod and Gauss estimates over [a, b], and the panel they make. The function is
/// evaluated once per Kronrod node; the Gauss rule reads the values at the odd positions, its own
/// nodes.
fn panel<F>(f: &mut F, rule: &KronrodRule, a: f64, b: f64) -> Result<Panel, QuadError>
where
    F: FnMut(Real) -> Result<Real, NumError>,
{
    let (centre, half) = (0.5 * a + 0.5 * b, 0.5 * b - 0.5 * a);
    let mut values = [0.0f64; MAX_NODES];
    for (v, t) in values.iter_mut().zip(rule.nodes) {
        *v = value_at(f, centre, half, *t)?;
    }
    let (mut kronrod, mut gauss) = (ExactSum::new(), ExactSum::new());
    for (k, v) in rule.kronrod.iter().zip(&values) {
        kronrod.add(k * v);
    }
    for (g, v) in rule.gauss.iter().zip(values.iter().skip(1).step_by(2)) {
        gauss.add(g * v);
    }
    let kronrod = half * kronrod.round()?.get();
    let gauss = half * gauss.round()?.get();
    Ok(Panel {
        a,
        b,
        value: Real::new(kronrod)?.get(),
        error: Real::new((kronrod - gauss).abs())?.get(),
    })
}

/// An estimate of ∫ₐᵇ f to within `tol` absolutely or `rel` relatively (the larger), by adaptive
/// bisection on Gauss–Kronrod rule `rule` (0 to 5: G7K15, G10K21, G15K31, G20K41, G25K51, G30K61),
/// with at most `cap` bisections.
///
/// # Errors
///
/// [`QuadError::BadInterval`] if `a ≥ b` or a tolerance is negative; [`QuadError::NoSuchRule`] for
/// a rule index above 5; [`QuadError::CapReached`] if the tolerance is not met within `cap`
/// bisections or [`MAX_PANELS`] panels; [`QuadError::TooNarrow`] if a panel cannot be split;
/// [`QuadError::Num`] if f fails or a sum overflows.
pub fn integrate<F>(
    mut f: F,
    a: Real,
    b: Real,
    tol: Real,
    rel: Real,
    rule: usize,
    cap: u32,
) -> Result<Integral, QuadError>
where
    F: FnMut(Real) -> Result<Real, NumError>,
{
    let (a, b, tol, rel) = (a.get(), b.get(), tol.get(), rel.get());
    if a >= b || tol < 0.0 || rel < 0.0 {
        return Err(QuadError::BadInterval);
    }
    let rule = GAUSS_KRONROD.get(rule).ok_or(QuadError::NoSuchRule)?;
    // At most 61 nodes a panel.
    let per_panel = u32::try_from(rule.nodes.len()).unwrap_or(u32::MAX);
    let first = panel(&mut f, rule, a, b)?;
    let mut panels = [first; MAX_PANELS];
    let mut count = 1usize;
    let mut bisections = 0u32;
    loop {
        let (mut value, mut error) = (ExactSum::new(), ExactSum::new());
        for p in panels.iter().take(count) {
            value.add(p.value);
            error.add(p.error);
        }
        let (value, error) = (value.round()?, error.round()?);
        let goal = if tol > rel * value.get().abs() {
            tol
        } else {
            rel * value.get().abs()
        };
        if error.get() <= goal {
            // count ≤ MAX_PANELS and bisections < MAX_PANELS, so neither the count nor
            // per_panel · (2·bisections + 1) ≤ 61 · 255 comes near u32::MAX.
            return Ok(Integral {
                value,
                error,
                panels: u32::try_from(count).unwrap_or(u32::MAX),
                evaluations: per_panel
                    .saturating_mul(bisections.saturating_mul(2).saturating_add(1)),
            });
        }
        if bisections >= cap || count >= MAX_PANELS {
            return Err(QuadError::CapReached);
        }
        // The first panel with the largest estimate: the last maximum of the panels taken in
        // reverse.
        let (worst, chosen) = panels
            .iter()
            .take(count)
            .enumerate()
            .rev()
            .max_by(|x, y| x.1.error.total_cmp(&y.1.error))
            .map_or((0, first), |(i, p)| (i, *p));
        let mid = 0.5 * chosen.a + 0.5 * chosen.b;
        if mid <= chosen.a || mid >= chosen.b {
            return Err(QuadError::TooNarrow);
        }
        let left = panel(&mut f, rule, chosen.a, mid)?;
        let right = panel(&mut f, rule, mid, chosen.b)?;
        // The left half takes the chosen panel's place, the right half the next free one.
        for (i, slot) in panels.iter_mut().enumerate() {
            if i == worst {
                *slot = left;
            } else if i == count {
                *slot = right;
            }
        }
        count = count.saturating_add(1);
        bisections = bisections.saturating_add(1);
    }
}
